contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: try a Deposit then Collect and assert the invariant
    function run(uint depositAmount, uint collectAmount, uint minSum, address logAddr) public payable {
        require(address(this).balance >= depositAmount, "need funds for deposit");
        // initialize c: set MinSum and Log, then mark initialized
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // record balances before actions
        uint beforeContractBal = address(c).balance;
        uint beforeMyBal = c.balances(address(this));

        // perform deposit to c sending Ether from this contract
        c.Deposit{value: depositAmount}();

        uint afterDepositContractBal = address(c).balance;
        uint afterDepositMyBal = c.balances(address(this));

        // sanity: deposit must have increased both tracked values by depositAmount
        // (we don't assert here; used later in final assertion)

        // attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read values after collect attempt
        uint finalContractBal = address(c).balance;
        uint finalMyBal = c.balances(address(this));

        // General rule asserted:
        // If Collect succeeded (not reverted) then:
        //  - caller's recorded balance decreased by exactly collectAmount
        //  - contract's ether balance decreased by exactly collectAmount
        //  - and the precondition for success held: the caller's balance before collect was >= MinSum and >= collectAmount
        assert(
            reverted || (
                // collect succeeded
                // recorded balance decreased by collectAmount
                afterDepositMyBal >= collectAmount && (afterDepositMyBal - finalMyBal) == collectAmount
                // contract balance decreased by collectAmount
                && (afterDepositContractBal - finalContractBal) == collectAmount
                // precondition: before invoking Collect, balances(address(this)) >= MinSum and >= collectAmount
                && afterDepositMyBal >= minSum && afterDepositMyBal >= collectAmount
            )
        );
    }

    // allow receiving Ether so this test contract can be funded
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try a Deposit and assert that if it does not revert then both the contract's
    // recorded balance for this contract and the contract's Ether balance increased by the amount sent.
    function run(uint depositAmount, uint minSum, address logAddr) public payable {
        // ensure this test contract has funds to send for the deposit
        require(address(this).balance >= depositAmount);

        // initialize c so Deposit can be used normally
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // read balances before
        uint beforeRecorded = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

        // attempt Deposit and capture revert
        bool reverted;
        try c.Deposit{value: depositAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after
        uint afterRecorded = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        // General rule: if Deposit did not revert then the recorded balance for this caller
        // increased by exactly depositAmount and the contract's Ether balance increased by exactly depositAmount.
        assert(reverted || (afterRecorded >= beforeRecorded && afterContractBal >= beforeContractBal && (afterRecorded - beforeRecorded) == depositAmount && (afterContractBal - beforeContractBal) == depositAmount));
    }

    // allow this test contract to receive Ether so it can fund deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try Collect and assert the invariant
    function run(uint depositAmount, uint collectAmount) public payable {
        // we will fund this test contract so it can call c.Deposit with depositAmount
        // require we have the Ether available
        require(address(this).balance >= depositAmount);

        // Ensure MinSum is low enough to allow collection if desired: set it to 0 before initialization
        // These setup calls are top-level state-changing calls as required.
        // SetMinSum and SetLogFile can only be called before c.Initialized(); choose a dummy log (this contract)
        c.SetMinSum(0);
        c.SetLogFile(address(this));

        // Record balances before interactions
        uint before_c_bal = address(c).balance;
        uint before_my_balInC = c.balances(address(this));

        // Deposit into c (may revert if e.g. overflow, but that's acceptable; we do it as a top-level call)
        // If depositAmount is 0 this is still a valid call and will just log.
        c.Deposit{value: depositAmount}();

        // After deposit, update observed balances
        uint after_deposit_c_bal = address(c).balance;
        uint after_deposit_my_balInC = c.balances(address(this));

        // Now attempt Collect and catch whether it reverts
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read final balances
        uint final_c_bal = address(c).balance;
        uint final_my_balInC = c.balances(address(this));

        // If Collect succeeded (not reverted) then it must have decreased the caller's recorded balance by collectAmount
        // and the contract's Ether balance by collectAmount. Otherwise (reverted) no guarantees needed.
        assert(reverted || (after_deposit_my_balInC >= collectAmount
               && after_deposit_my_balInC - final_my_balInC == collectAmount
               && after_deposit_c_bal >= collectAmount
               && after_deposit_c_bal - final_c_bal == collectAmount));
    }

    // allow receiving Ether when SetLogFile pointed to this contract (Log.AddMessage may call into this)
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function
    function run(uint depositAmount, uint collectAmount, uint minSum) public payable {
        // ensure this contract can fund the Deposit call
        require(address(this).balance >= depositAmount);

        // Set configuration before Initialized()
        c.SetMinSum(minSum);
        c.SetLogFile(address(this));

        // Record before-values
        uint before_c_bal = address(c).balance;
        uint before_my_balInC = c.balances(address(this));
        uint before_min = c.MinSum();

        // Deposit funds (top-level state-changing call)
        c.Deposit{value: depositAmount}();

        // Values after deposit, before Collect
        uint after_c_bal = address(c).balance;
        uint after_my_balInC = c.balances(address(this));

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Values after Collect
        uint final_c_bal = address(c).balance;
        uint final_my_balInC = c.balances(address(this));
        uint after_min = c.MinSum();

        // General rule asserted:
        // If Collect succeeded then:
        // 1) the caller's recorded balance decreased exactly by collectAmount
        // 2) the contract's Ether balance decreased exactly by collectAmount
        // 3) the Collect could only succeed if the caller's balance before Collect was >= MinSum and >= collectAmount
        // Additionally, SetMinSum should persist (MinSum unchanged by Deposit/Collect)
        assert(
            (!reverted &&
              after_my_balInC >= collectAmount &&
              after_my_balInC - final_my_balInC == collectAmount &&
              after_c_bal >= collectAmount &&
              after_c_bal - final_c_bal == collectAmount &&
              // check preconditions for success were met (use values right before Collect)
              after_my_balInC >= after_min &&
              after_my_balInC >= collectAmount
            )
            ||
            // If Collect reverted, we place no requirements about changes (other than MinSum unchanged)
            (reverted)
        );

        // Ensure MinSum was not modified by Deposit or Collect (it was set before)
        assert(after_min == before_min);
    }

    // allow receiving Ether for Log callback
    receive() external payable { }
}

