contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run will: deposit some ether into c from this contract, then attempt Collect with some amount.
    // Parameters: depositAmt = amount sent into Deposit; collectAmt = amount passed to Collect.
    function run(uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient funds to deposit");

        // Record balances before any calls
        uint before_c_balance = address(c).balance;
        uint before_my_balance_in_c = c.balances(address(this));

        // Make a deposit to set up funds inside c for this test contract
        // Use the Deposit() entrypoint by sending ether to c.deposit
        c.Deposit{value: depositAmt}();

        // After deposit, record balances prior to Collect
        uint after_deposit_c_balance = address(c).balance;
        uint after_deposit_my_balance_in_c = c.balances(address(this));

        // Attempt Collect and catch whether it reverted
        bool collect_reverted;
        try c.Collect(collectAmt) {
            collect_reverted = false;
        } catch {
            collect_reverted = true;
        }

        // Read balances after Collect (or after failed Collect)
        uint final_c_balance = address(c).balance;
        uint final_my_balance_in_c = c.balances(address(this));

        // General property: If Collect did not revert, then my balance in c decreased by collectAmt
        // and c's ETH balance decreased by collectAmt. If Collect reverted, no requirement.
        assert(collect_reverted || (after_deposit_my_balance_in_c >= collectAmt
               && after_deposit_my_balance_in_c - final_my_balance_in_c == collectAmt
               && after_deposit_c_balance >= collectAmt
               && after_deposit_c_balance - final_c_balance == collectAmt));
    }

    // Allow this contract to receive ETH refunds from c.call in Collect
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We deposit some ETH first so there is a chance Collect can succeed.
    // Params: depositAmt = amount to deposit into c; collectAmt = amount passed to Collect.
    function run(uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient funds to deposit");

        // ensure MinSum is 0 so that Collect can be allowed by MinSum check if needed
        // (we can only call public methods; SetMinSum may revert if initialized, but freshly deployed c is uninitialized)
        bool setMin_ok;
        try c.SetMinSum(0) {
            setMin_ok = true;
        } catch {
            setMin_ok = false;
        }

        // record balances before any action
        uint before_my_balance_in_c = c.balances(address(this));
        uint before_c_balance = address(c).balance;

        // perform a deposit to give the test contract funds inside c
        c.Deposit{value: depositAmt}();

        // record immediately before attempting Collect
        uint just_before_my_balance_in_c = c.balances(address(this));
        uint just_before_c_balance = address(c).balance;

        // attempt Collect and record whether it reverted
        bool collect_reverted;
        try c.Collect(collectAmt) {
            collect_reverted = false;
        } catch {
            collect_reverted = true;
        }

        // read balances after Collect attempt
        uint final_my_balance_in_c = c.balances(address(this));
        uint final_c_balance = address(c).balance;

        // General invariant: if Collect did not revert then the caller's recorded balance in c strictly decreases
        // (i.e., final_my_balance_in_c < just_before_my_balance_in_c). If Collect reverted, no requirement.
        assert(collect_reverted || final_my_balance_in_c < just_before_my_balance_in_c);
    }

    // allow receiving ETH from c when Collect does a call
    receive() external payable { }
}

