contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: depositAmt to deposit into c so we can attempt Collect, collectAmt to request
    function run(uint depositAmt, uint collectAmt, uint newMin) public payable {
        // ensure this test contract has enough ETH to perform the deposit
        require(address(this).balance >= depositAmt, "insufficient funds to deposit");

        // Try to set MinSum to newMin (may revert if c already initialized); ignore revert
        try c.SetMinSum(newMin) {
        } catch {
        }

        // Record c balance and recorded balance for this contract before Deposit
        uint before_c_eth = address(c).balance;
        uint before_recorded = c.balances(address(this));

        // Deposit amount depositAmt into c to fund recorded balance (this may revert if something wrong)
        c.Deposit{value: depositAmt}();

        // Record values just before Collect
        uint just_before_recorded = c.balances(address(this));
        uint just_before_c_eth = address(c).balance;

        // Attempt Collect and note whether it reverted
        bool collect_reverted;
        try c.Collect(collectAmt) {
            collect_reverted = false;
        } catch {
            collect_reverted = true;
        }

        // Observe after-state
        uint after_recorded = c.balances(address(this));
        uint after_c_eth = address(c).balance;
        uint minSum = c.MinSum();

        // General rule: if Collect succeeded then either (1) the contract had sufficient recorded balance
        // and the contract's ETH balance decreased by at least collectAmt, OR (2) the recorded balance was below MinSum
        // (the latter allows Collect to silently do nothing). This captures that successful Collect cannot create ETH out of thin air
        // unless Collect was not allowed by MinSum. Expressed to be provable for all inputs.
        assert(collect_reverted || (
            // If not reverted, then either the caller's recorded balance was below MinSum (so Collect's body didn't run),
            // or contract ETH decreased by at least collectAmt and recorded balance did not increase.
            (just_before_recorded < minSum) || (just_before_c_eth >= after_c_eth && just_before_c_eth - after_c_eth >= collectAmt)
        ));
    }

    // Receive to accept ETH forwarded by c during Collect
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: try to Collect amount `am` after setting MinSum and funding the contract
    function run(uint minSum, uint depositAmt, uint am) public payable {
        require(address(this).balance >= depositAmt, "need funds to deposit");

        // initialize c: set MinSum and set LogFile to some address (use address(this)) before Initialized is called
        c.SetMinSum(minSum);
        c.SetLogFile(address(this));

        // Deposit into c from this test contract if depositAmt>0
        if (depositAmt > 0) {
            // ensure we have the Ether available
            c.Deposit{value: depositAmt}();
        }

        // read balances and contract balance before Collect
        uint beforeBal = c.balances(address(this));
        uint beforeCbal = address(c).balance;

        bool reverted;
        // attempt Collect; catch revert
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = c.balances(address(this));
        uint afterCbal = address(c).balance;

        // General rule: if Collect did not revert, then the recorded balance decreased by exactly am
        // (since Collect only allows when balances[msg.sender] >= MinSum and >= am), and the contract's
        // Ether balance decreased by at least am (it may revert on transfer otherwise). If Collect reverted
        // then no requirement (reverted==true allowed).
        assert(reverted || (beforeBal >= am && beforeBal - afterBal == am && beforeCbal >= afterCbal && (beforeCbal - afterCbal) >= am));
    }

    // Receive to accept refunds/transfers if any
    receive() external payable {}
}

