            ))
            // Revert case: precondition failed (either insufficient recorded balance for minSum or for requested amount)
            || (reverted && !(bal_before >= minSum && bal_before >= collectAmt))
        );
    }

    // Allow receiving Ether when Collect sends funds back to this contract
    receive() external payable {}
}

