        }

        // read balance just before Collect
        uint preCollectBal = c.balances(address(this));

        // attempt Collect; top-level state-changing call wrapped in try/catch
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read balance after Collect attempt
        uint postCollectBal = c.balances(address(this));

        // General rule: postCollectBal is never greater than preCollectBal
        assert(postCollectBal <= preCollectBal);
    }

    receive() external payable {}
}

