    function run(uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance for deposit");

        // read before values
        uint beforeContractBal = address(c).balance;
        uint beforeRecorded = c.balances(address(this));

        // perform a Deposit sending depositAmt wei to c
        c.Deposit{value: depositAmt}();

        // read intermediate values after deposit
        uint midContractBal = address(c).balance;
        uint midRecorded = c.balances(address(this));

        // ensure deposit had the expected observable effect (sanity): contract balance and recorded for this increased by depositAmt
        // Not part of the final assert; it's a require to avoid meaningless cases
        require(midContractBal == beforeContractBal + depositAmt && midRecorded == beforeRecorded + depositAmt);

        // attempt Collect and catch whether it reverted
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after values
        uint afterContractBal = address(c).balance;
        uint afterRecorded = c.balances(address(this));

        // General rule asserted: if Collect succeeded then the combined observable funds (contract balance + recorded balance of this) decreased by at least collectAmt
        // If Collect reverted then no requirement here (but collectReverted captures that).
        assert(collectReverted || ( (int(beforeContractBal + midRecorded) - int(afterContractBal + afterRecorded)) >= int(collectAmt) ));
    }

